package br.edu.ifrn.sistemachamados.controller;
import br.edu.ifrn.sistemachamados.dto.request.*;import br.edu.ifrn.sistemachamados.dto.response.*;import br.edu.ifrn.sistemachamados.mapper.ApiMapper;import br.edu.ifrn.sistemachamados.model.*;import br.edu.ifrn.sistemachamados.service.*;import jakarta.validation.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/categorias") public class CategoriaController{final CategoriaService s;public CategoriaController(CategoriaService s){this.s=s;}Categoria e(CategoriaRequest r){Categoria x=new Categoria();x.setNome(r.nome());x.setDescricao(r.descricao());Setor z=new Setor();z.setId(r.setorId());x.setSetor(z);return x;}@PostMapping public ResponseEntity<CategoriaResponse> post(@Valid @RequestBody CategoriaRequest r){return ResponseEntity.status(201).body(ApiMapper.categoria(s.cadastrar(e(r))));}@GetMapping public PageResponse<CategoriaResponse> list(@RequestParam(required=false)String nome,@RequestParam(required=false)Long setorId,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer size,@RequestParam(required=false)String[] sort){return PageResponse.of(s.listar(nome,setorId,WebSupport.page(page,size,sort)),ApiMapper::categoria);}@GetMapping("/{id}")public CategoriaResponse get(@PathVariable Long id){return ApiMapper.categoria(s.buscarPorId(id));}@PutMapping("/{id}")public CategoriaResponse put(@PathVariable Long id,@Valid @RequestBody CategoriaRequest r){return ApiMapper.categoria(s.atualizar(id,e(r)));}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void del(@PathVariable Long id){s.excluir(id);}}
